package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance() {
        Element element = Parser.parseBodyFragment("<div></div>").body().child(0);
        // Tests: if (this == o) return true;
        Assert.assertTrue(element.equals(element));
    }

    @Test
    public void testEquals_Null() {
        Element element = Parser.parseBodyFragment("<div></div>").body().child(0);
        // Tests: if (o == null || getClass() != o.getClass()) return false;
        Assert.assertFalse(element.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Element element = Parser.parseBodyFragment("<div></div>").body().child(0);
        TextNode textNode = Parser.parseBodyFragment("text").body().firstChild();
        // Tests: if (o == null || getClass() != o.getClass()) return false;
        Assert.assertFalse(element.equals(textNode));
    }

    @Test
    public void testEquals_DifferentInstanceSameContent() {
        // Note: The provided implementation of equals has a bug/specific behavior:
        // It returns 'this == o' at the end, which means even if super.equals is true,
        // it only returns true if they are the exact same instance.
        // This test verifies the current logic provided in the prompt.
        Element element1 = Parser.parseBodyFragment("<div></div>").body().child(0);
        Element element2 = Parser.parseBodyFragment("<div></div>").body().child(0);

        // super.equals(o) for jsoup nodes usually checks identity or structural equality depending on version,
        // but the provided code explicitly ends with 'return this == o;'
        // Therefore, even if they represent the same HTML, if they are different objects, it returns false.
        Assert.assertFalse(element1.equals(element2));
    }

    @Test
    public void testEquals_SuperEqualsFalse() {
        // To trigger 'if (!super.equals(o)) return false;'
        // We need two elements that are NOT equal according to the super class (Node.equals)
        // but are of the same class.
        Element element1 = Parser.parseBodyFragment("<div>id1</div>").body().child(0);
        Element element2 = Parser.parseBodyFragment("<div>id2</div>").body().child(0);

        Assert.assertFalse(element1.equals(element2));
    }
}
